<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue';
import SyncSubtreePlan from './SyncSubtreePlan.vue';
import {formatBytes} from './format-bytes';
import {subtreeActions,parseSubtreePage,type SubtreeReview,type Resolution} from './sync-resolution';
const props=defineProps<{decision:Resolution;disabled?:boolean}>(),emit=defineEmits<{authenticationRequired:[]}>();
const review=computed(()=>props.decision.subtree_review!),offset=ref(0),rows=ref<SubtreeReview['items']>([]),loading=ref(false),error=ref(''),fresh=ref(!review.value.paged),loaded=ref(false);
const visible=computed(()=>review.value.paged?rows.value:review.value.items.slice(offset.value,offset.value+100));
const total=computed(()=>review.value.item_count||String(review.value.items.length)),more=computed(()=>BigInt(offset.value)+BigInt(visible.value.length)<BigInt(total.value));
let active=true,generation=0,controller:AbortController|undefined;
const current=(n:number)=>active&&n===generation;
function invalidate(){generation++;controller?.abort();loading.value=false}
async function load(at=offset.value){
 if(!active||props.disabled||loading.value||!Number.isSafeInteger(at)||at<0)return;
 if(!review.value.paged){offset.value=at;fresh.value=true;return}
 const n=++generation;controller?.abort();controller=new AbortController();loading.value=true;fresh.value=false;
 try{const response=await fetch('/api/sync/resolutions/'+props.decision.id+'/subtree?offset='+at,{credentials:'same-origin',signal:controller.signal});if(!current(n))return;if(response.status===401){stop();emit('authenticationRequired');return}if(!response.ok)throw Error((await response.text()).slice(0,1000)||'固定子项暂不可读');const data=await response.json();if(!current(n))return;rows.value=parseSubtreePage(data,props.decision,at);offset.value=at;loaded.value=true;fresh.value=true;error.value=''}catch(e){if(current(n))error.value=e instanceof Error?e.message:String(e)}finally{if(current(n))loading.value=false}
}
function reset(){invalidate();offset.value=0;rows.value=[];loaded.value=false;fresh.value=!review.value.paged;error.value='';if(active&&review.value.paged)void load(0)}
function stop(){active=false;invalidate()}
function restore(){active=true;if(review.value.paged)void load()}
watch(()=>props.decision.id,reset);watch(()=>props.disabled,v=>{if(v)invalidate();else if(active&&!loaded.value&&review.value.paged)void load(0)});
onMounted(()=>{if(review.value.paged)void load(0);window.addEventListener('pagehide',stop);window.addEventListener('pageshow',restore)});onUnmounted(()=>{stop();window.removeEventListener('pagehide',stop);window.removeEventListener('pageshow',restore)});
</script>
<template><section data-testid="sync-subtree-impact" class="subtree-impact"><h3>目录与删除冲突 · 子项影响</h3><p>{{review.note}}</p><p class="muted">范围 {{review.root}} · 共 {{total}} 个文件或目录。下表列出逐项影响；固定步骤另列，执行前请完成下方整树核对。</p><p v-if="loading" role="status">正在读取固定子项页…</p><p v-if="error" class="notice danger" role="alert">{{error}}<span v-if="loaded"> · 保留上次已读取的固定页。</span></p><p v-if="review.plan_version" class="muted">已固定 {{review.plan_step_count}} 项有序步骤；支持整段子树只读重核，完整重核通过后可确认执行。<a class="button secondary compact" :href="'/api/sync/resolutions/'+decision.id+'/subtree-plan?export=1'">导出完整有序步骤</a></p><div class="table-wrap"><table><thead><tr><th>来源</th><th>文件数</th><th>文件内容大小</th></tr></thead><tbody><tr><td>本地快照</td><td>{{review.local_files}}</td><td>{{formatBytes(review.local_bytes)}}</td></tr><tr><td>网盘快照</td><td>{{review.remote_files}}</td><td>{{formatBytes(review.remote_bytes)}}</td></tr></tbody></table><table><thead><tr><th>项目路径</th><th>本地原项</th><th>网盘原项</th><th>本地影响 / 目标</th><th>网盘影响 / 目标</th></tr></thead><tbody><tr v-for="item in visible" :key="item.path"><td>{{item.path}}</td><td><template v-if="item.local">{{item.local.directory?'📁 文件夹':'📄 '+formatBytes(item.local.size)}}<small>ID {{item.local.id}}</small></template><span v-else>快照未见</span></td><td><template v-if="item.remote">{{item.remote.directory?'📁 文件夹':'📄 '+formatBytes(item.remote.size)}}<small>ID {{item.remote.id}}</small></template><span v-else>快照未见</span></td><td><strong :class="{muted:item.local_action==='keep'}">{{subtreeActions[item.local_action]}}</strong><small>{{item.local_target||'处理后不保留原位置'}}</small><small v-if="item.restore_local_target">恢复网盘项到 {{item.restore_local_target}}</small></td><td><strong :class="{muted:item.remote_action==='keep'}">{{subtreeActions[item.remote_action]}}</strong><small>{{item.remote_target||'处理后不保留原位置'}}</small></td></tr></tbody></table></div><footer><button class="button secondary compact" :disabled="loading||disabled||!fresh||offset===0" @click="load(Math.max(0,offset-100))">上一页子项</button><span>第 {{Math.floor(offset/100)+1}} 页 · 每页最多 100 项</span><button class="button secondary compact" :disabled="loading||disabled||!fresh||!more" @click="load(offset+100)">下一页子项</button><button v-if="review.paged" class="button secondary compact" :disabled="loading||disabled" @click="load()">重新读取本页</button><a class="button secondary compact" :href="'/api/sync/resolutions/'+decision.id+'?export=1'">导出完整固定清单</a></footer><SyncSubtreePlan v-if="review.plan_version" :decision="decision" :disabled="disabled" @authentication-required="emit('authenticationRequired')"/><p class="muted">单个目录身份或 0 B 大小不能证明子项未变。执行前必须重新核对完整子树，并在下方明确确认。</p></section></template>
<style scoped>.subtree-impact{border-top:1px solid #dce5ef;padding-top:12px;margin-top:18px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px;text-align:left;margin:12px 0}th,td{padding:8px 10px;border-bottom:1px solid #e4eaf2;vertical-align:top;overflow-wrap:anywhere}th{background:#f5f7fb;white-space:nowrap}small{display:block;color:#65748b;margin-top:4px}strong{font-weight:500}footer{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.muted{color:#65748b}</style>
